import PulsoLinkCore

/**
 * Near 室内交友聚会门面（对应 Android `IndoorSocialService`、WEB `hooks/indoorSocial.ts`）：
 * 读走 [IndoorSocialQueryStore]；写成功后一次 [IndoorSocialEventBus.invalidate]。
 */
struct IndoorSocialService: Sendable {
    let repository: IndoorSocialRepository
    let query: IndoorSocialQueryStore
    let eventBus: IndoorSocialEventBus
    let exploreQuery: ExploreQueryStore

    static let rosterPageSize = IndoorSocialQueryStore.rosterPageSize

    /** 我主持的活动的收款清单，分页；这个运动的任何写操作都会让它重拉。 */
    @MainActor
    func pageHostedChecklists(isAllSettled: Bool) -> PagedList<HostedChecklistRowUi, Int> {
        let repository = repository
        return .offset(invalidates: { eventBus.signals { _ in true } }) { offset, limit in
            let page = try await repository.listHostedPaymentChecklists(
                IndoorSocialListHostedPaymentChecklistsRequest(offset: offset, limit: limit, isAllSettled: isAllSettled)
            )
            return ListWithTotal(items: page.items.map(HostedChecklistRowUi.init), total: page.total)
        }
    }

    /** 我自己欠的收款行，分页。 */
    @MainActor
    func pageMyPaymentItems(paid: Bool) -> PagedList<MyChecklistItemRowUi, Int> {
        let repository = repository
        return .offset(invalidates: { eventBus.signals { _ in true } }) { offset, limit in
            let page = try await repository.listMyPaymentChecklistItems(
                IndoorSocialListMyPaymentChecklistItemsRequest(offset: offset, limit: limit, paid: paid)
            )
            return ListWithTotal(items: page.items.map(MyChecklistItemRowUi.init), total: page.total)
        }
    }

    func prefetchDetail(activityId: String) {
        query.prefetchDetail(activityId: activityId)
    }

    func incrementView(activityId: String) async throws -> IncrementIndoorSocialActivityViewResponse {
        let response = try await repository.incrementIndoorSocialActivityView(activityId: activityId)
        await query.overlayView(activityId: activityId, view: response.view)
        await exploreQuery.overlayView(activityId: activityId, view: response.view)
        return response
    }

    func create(_ body: CreateIndoorSocialActivityRequest) async throws -> CreateIndoorSocialActivityResponse {
        let response = try await repository.createIndoorSocialActivity(body)
        eventBus.invalidate()
        return response
    }

    func join(activityId: String, _ body: JoinIndoorSocialActivityRequest = JoinIndoorSocialActivityRequest()) async throws -> JoinIndoorSocialActivityResponse {
        let response = try await repository.joinIndoorSocialActivity(activityId: activityId, body)
        eventBus.invalidate()
        return response
    }

    func getMyRegistrationPayment(activityId: String) async throws -> PaymentHoldActivity {
        try await repository.getMyRegistrationPayment(activityId: activityId)
    }

    func payMyRegistrationPayment(activityId: String, paymentMethodId: String) async throws -> PaymentAttempt {
        let attempt = try await repository.payMyRegistrationPayment(activityId: activityId, PayPaymentRequest(paymentMethodId: paymentMethodId))
        invalidate()
        return attempt
    }

    /** Stripe 付款成功后 webhook 才改报名状态，让订阅方重拉。 */
    func invalidate() {
        eventBus.invalidate()
    }

    func exit(activityId: String) async throws -> IndoorSocialRegistration {
        let registration = try await repository.exitIndoorSocialActivity(activityId: activityId)
        eventBus.invalidate()
        return registration
    }

    func end(activityId: String) async throws {
        try await repository.endIndoorSocialActivity(activityId: activityId)
        eventBus.invalidate()
    }

    func patchBasic(activityId: String, _ body: PatchIndoorSocialActivityBasicRequest) async throws {
        try await repository.patchIndoorSocialActivityBasic(activityId: activityId, body)
        eventBus.invalidate()
    }

    func markPaymentItemPaid(itemId: String) async throws {
        try await repository.markPaymentChecklistItemPaid(itemId: itemId)
        eventBus.invalidate()
    }

    func markPaymentItemUnpaid(itemId: String) async throws {
        try await repository.markPaymentChecklistItemUnpaid(itemId: itemId)
        eventBus.invalidate()
    }

    func settleAll(activityId: String) async throws -> IndoorSocialPaymentChecklistResponse {
        let response = try await repository.settleAllPaymentChecklist(activityId: activityId)
        eventBus.invalidate()
        return response
    }

    func remindItems(activityId: String, itemIds: [String]) async throws {
        try await repository.remindPaymentChecklistItems(activityId: activityId, itemIds: itemIds)
        eventBus.invalidate()
    }
}

extension HostedChecklistRowUi {
    init(_ item: IndoorSocialHostedPaymentChecklistItem) {
        self.init(
            checklistId: item.id,
            activityId: item.indoorSocialActivityId,
            title: item.title.isEmpty ? String(item.indoorSocialActivityId.prefix(8)) : item.title,
            venueName: item.venueName ?? item.address,
            startsAt: item.startsAt,
            isAllSettled: item.isAllSettled
        )
    }
}

extension MyChecklistItemRowUi {
    init(_ item: IndoorSocialMyPaymentChecklistItem) {
        self.init(
            itemId: item.id,
            activityId: item.indoorSocialActivityId,
            title: item.title.isEmpty ? String(item.indoorSocialActivityId.prefix(8)) : item.title,
            venueName: item.venueName ?? item.address,
            startsAt: item.startsAt,
            paid: item.paid,
            priceAmount: item.priceAmount,
            currency: item.currency
        )
    }
}
